local SawSetMaker = {}
local PRODUCTS = {
    iron_saw_set = { name = "Železna nastavljiva žaga", ironCost = 4, woodCost = 3, leatherCost = 1, time = 5, cost = 175, prestige = 4, happiness = 2, description = "Železna nastavljiva žaga za razrez lesa." },
    bronze_saw_set = { name = "Bronasta nastavljiva žaga", bronzeCost = 4, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 425, prestige = 6, happiness = 3, description = "Bronasta nastavljiva žaga za fino rezanje." },
    silver_saw_set = { name = "Srebrna nastavljiva žaga", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 1025, prestige = 11, happiness = 4, description = "Srebrna nastavljiva žaga za plemiške mizarje." },
    gilded_saw_set = { name = "Pozlačena nastavljiva žaga", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2200, prestige = 20, happiness = 5, description = "Pozlačena nastavljiva žaga za dvorne mizarje." },
    jewel_set_saw_set = { name = "Draguljasta nastavljiva žaga", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4750, prestige = 36, happiness = 7, description = "Draguljasta nastavljiva žaga za kraljevske mizarje." },
    royal_sovereign_saw_set = { name = "Kraljevski suverena nastavljiva žaga", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 10200, prestige = 68, happiness = 13, description = "Suverena nastavljiva žaga z biseri za krono." },
}
local BUILDINGS = {
    sawset_workshop = { name = "Žagarska delavnica", cost = { gold = 350, wood = 190, stone = 135, iron = 9 }, upkeep = 6, qualityBonus = 5 },
    sawset_house = { name = "Žagarska hiša", cost = { gold = 1240, wood = 375, stone = 275, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_sawset_atelier = { name = "Mojstrski žagarski atelje", cost = { gold = 3100, wood = 435, stone = 525, silver = 36, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_sawset_palace = { name = "Suverena žagarska palača", cost = { gold = 13200, wood = 660, stone = 840, gold = 85, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
SawSetMaker.ironStock = 16; SawSetMaker.bronzeStock = 14; SawSetMaker.woodStock = 14; SawSetMaker.leatherStock = 10; SawSetMaker.silverStock = 8; SawSetMaker.goldStock = 6; SawSetMaker.jewelStock = 4; SawSetMaker.pearlStock = 4
SawSetMaker.productStock = {}; SawSetMaker.buildings = {}; SawSetMaker.maker = nil; SawSetMaker.activeMaking = {}; SawSetMaker.totalProducts = 0; SawSetMaker.dayTimer = 0
function SawSetMaker.init() SawSetMaker.ironStock=16; SawSetMaker.bronzeStock=14; SawSetMaker.woodStock=14; SawSetMaker.leatherStock=10; SawSetMaker.silverStock=8; SawSetMaker.goldStock=6; SawSetMaker.jewelStock=4; SawSetMaker.pearlStock=4; SawSetMaker.productStock={}; SawSetMaker.buildings={}; SawSetMaker.maker=nil; SawSetMaker.activeMaking={}; SawSetMaker.totalProducts=0; SawSetMaker.dayTimer=0; print("[SawSetMaker] Royal Saw Set Maker System initialized (6 products, 4 buildings)") end
function SawSetMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SawSetMaker.maker={name=n or ("Žagar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žagar najet: %s (spretnost: %d)",SawSetMaker.maker.name,s),"success") end; return true end
function SawSetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SawSetMaker.build(id) local ok,e=SawSetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SawSetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SawSetMaker.getQualityBonus() local b=0; for _,bd in ipairs(SawSetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SawSetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SawSetMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SawSetMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SawSetMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SawSetMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SawSetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SawSetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SawSetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SawSetMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SawSetMaker.buildings==0 then return false,"Potrebna žagarska delavnica" end; if not SawSetMaker.maker then return false,"Potreben žagar" end; return true end
function SawSetMaker.make(pt,qty) qty=qty or 1; local ok,e=SawSetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SawSetMaker.ironStock=SawSetMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SawSetMaker.bronzeStock=SawSetMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SawSetMaker.woodStock=SawSetMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SawSetMaker.leatherStock=SawSetMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SawSetMaker.silverStock=SawSetMaker.silverStock-d.silverCost*qty end; if d.goldCost then SawSetMaker.goldStock=SawSetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SawSetMaker.jewelStock=SawSetMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SawSetMaker.pearlStock=SawSetMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SawSetMaker.maker then t=math.max(1,t-math.floor(SawSetMaker.maker.skill/13)) end; table.insert(SawSetMaker.activeMaking,{id="sawset_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SawSetMaker.completeMaking(m) local q=1.0+(SawSetMaker.getQualityBonus()/100); if SawSetMaker.maker then q=q+(SawSetMaker.maker.skill/140) end; q=math.min(2.5,q); SawSetMaker.productStock[m.productType]=(SawSetMaker.productStock[m.productType] or 0)+m.quantity; SawSetMaker.totalProducts=SawSetMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SawSetMaker.maker then SawSetMaker.maker.itemsMade=SawSetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SawSetMaker.maker.skill=math.min(100,SawSetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žaga izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sawset.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SawSetMaker.update(dt) if not _G.state then return end; SawSetMaker.dayTimer=SawSetMaker.dayTimer+dt; if SawSetMaker.dayTimer>=30 then SawSetMaker.dayTimer=0; for i=#SawSetMaker.activeMaking,1,-1 do local m=SawSetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SawSetMaker.completeMaking(m); table.remove(SawSetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SawSetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SawSetMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SawSetMaker.getStats() return {ironStock=SawSetMaker.ironStock,bronzeStock=SawSetMaker.bronzeStock,woodStock=SawSetMaker.woodStock,leatherStock=SawSetMaker.leatherStock,silverStock=SawSetMaker.silverStock,goldStock=SawSetMaker.goldStock,jewelStock=SawSetMaker.jewelStock,pearlStock=SawSetMaker.pearlStock,productStock=SawSetMaker.productStock,numBuildings=#SawSetMaker.buildings,hasMaker=SawSetMaker.maker~=nil,makerName=SawSetMaker.maker and SawSetMaker.maker.name or "—",makerSkill=SawSetMaker.maker and SawSetMaker.maker.skill or 0,activeMaking=#SawSetMaker.activeMaking,totalProducts=SawSetMaker.totalProducts} end
return SawSetMaker
